1261:Result BinaryReaderObjdump::BeginSection(Index section_index,
1262:                                         BinarySection section_code,
1263:                                         Offset size) {
1264:  BinaryReaderObjdumpBase::BeginSection(section_index, section_code, size);
1265:
1266:  // |section_name| and |match_name| are identical for known sections. For
1267:  // custom sections, |section_name| is "Custom", but |match_name| is the name
1268:  // of the custom section.
1269:  const char* section_name = wabt::GetSectionName(section_code);
1270:  std::string match_name(GetSectionName(section_index));
1271:
1272:  bool section_match = !options_->section_name ||
1273:                       !strcasecmp(options_->section_name, match_name.c_str());
1274:  if (section_match) {
1275:    section_found_ = true;
1276:  }
1277:
1278:  switch (options_->mode) {
1279:    case ObjdumpMode::Headers:
1280:      printf("%9s start=%#010" PRIzx " end=%#010" PRIzx " (size=%#010" PRIoffset
1281:             ") ",
1282:             section_name, state->offset, state->offset + size, size);
1283:      break;
1284:    case ObjdumpMode::Details:
1285:      if (section_match) {
1286:        printf("%s", section_name);
1287:        // All known section types except the Start and DataCount sections have
1288:        // a count in which case this line gets completed in OnCount().
1289:        if (section_code == BinarySection::Start ||
1290:            section_code == BinarySection::DataCount ||
1291:            section_code == BinarySection::Custom) {
1292:          printf(":\n");
1293:        }
1294:        print_details_ = true;
1295:      } else {
1296:        print_details_ = false;
1297:      }
1298:      break;
1299:    case ObjdumpMode::RawData:
1300:      if (section_match) {
1301:        printf("\nContents of section %s:\n", section_name);
1302:        out_stream_->WriteMemoryDump(data_ + state->offset, size, state->offset,
1303:                                     PrintChars::Yes);
1304:      }
1305:      break;
1306:    case ObjdumpMode::Prepass:
1307:    case ObjdumpMode::Disassemble:
1308:      break;
1309:  }
